    <div className="view">
      <button className="back" style={{ display: "inline-flex", alignItems: "center", gap: "6px", color: "var(--text-2)", fontSize: "13.5px", fontWeight: 600, marginBottom: "14px", cursor: "pointer", background: "none", border: "none" }} onClick={() => app.go("courses")}><Ic.chevR style={{ transform: "rotate(180deg)" }} /> All courses</button>
      <h1 style={{ fontSize: "clamp(22px,4vw,30px)", margin: "10px 0 4px" }}>{c.name}</h1>
