      <div className="eyebrow">{c.code} · Topic {String(t.topicIndex + 1).padStart(2, "0")}</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,30px)", margin: "8px 0 6px" }}>{t.title}</h1>
      <div className="card">
        <p style={{ color: "var(--text-2)", margin: 0 }}>Content coming soon. The full lesson, AI tutor, theory questions and MCQs are on the way.</p>
      </div>
    </div>
  );
}

function DailyView({ app }) {
  const jsDay = new Date().getDay();
  const d = DAILY[jsDay];
  const c = courseById(d?.courseId || "ana");
  const alreadyDone = app.progress.dailyDone?.[todayKey()];
  const [chosen, setChosen] = useState(null);
  const [reveal, setReveal] = useState(!!alreadyDone);

  const submit = () => {
    if (chosen === null) return;
    setReveal(true);
    if (!alreadyDone) app.recordDaily(chosen === d.a);
  };

  if (!d) return <div className="view"><div className="card">No question today.</div></div>;

  return (
    <div className="view">
      <div className="eyebrow">Daily question · {new Date().toLocaleDateString("en-GB", { weekday: "long" })}</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>Keep the streak alive</h1>
      <div className="card" style={{ marginTop: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <span className="day-tag" style={{ fontFamily: "var(--mono)", fontSize: "10px", textTransform: "uppercase", letterSpacing: ".14em", color: "var(--amber-2)", background: "var(--amber-dim)", padding: "3px 8px", borderRadius: "6px", fontWeight: 600, display: "inline-block" }}>{c.name}</span>
          <span className="chip streakchip"><Ic.flame /><span className="val">{app.progress.streak}</span> day streak</span>
        </div>
        <h3 style={{ fontSize: 18, lineHeight: 1.4, marginBottom: 16 }}>{d.q}</h3>
        {d.o.map((opt, oi) => {
          let cls = "opt";
          if (reveal) { if (oi === d.a) cls += " correct"; else if (oi === chosen) cls += " wrong"; }
          else if (oi === chosen) cls += " sel";
          return <button className={cls} key={oi} disabled={reveal} onClick={() => setChosen(oi)} style={{ width: "100%", textAlign: "left", padding: "14px 15px", border: "1px solid var(--line)", borderRadius: "12px", marginBottom: "10px", display: "flex", gap: "12px", alignItems: "flex-start", transition: "border-color .14s,background .14s", background: "var(--bg-2)", cursor: "pointer" }}><span className="key" style={{ fontFamily: "var(--mono)", fontWeight: 700, color: "var(--text-3)", flexShrink: 0 }}>{"ABCD"[oi]}</span><span>{opt}</span></button>;
        })}
        {reveal ? (
          <div className="card" style={{ marginTop: 6, background: "var(--bg-3)" }}>
            <div style={{ fontSize: 14, color: "var(--text-2)" }}><strong style={{ color: "var(--text)" }}>Why: </strong>{d.w}</div>
          </div>
        ) : (
          <button className="btn btn-a" style={{ marginTop: 8 }} disabled={chosen === null} onClick={submit}>Submit answer</button>
        )}
      </div>
    </div>
  );
}

